CREATE PROCEDURE SP_Vue_OrderinHand_ALL   AS 
BEGIN 

DECLARE @sql1 NVARCHAR(MAX);

SET @sql1 = 'ALTER VIEW Vue_Rpt_OrderReg as 

SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,Avg(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName, IsNull(Sum(isnull(DespatchPcs,0)),0) as DespatchPcs, DespatchDt,Sum(Amount) As Amount, Sum(DespAmount) As DespAmount FROM (
 SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,Xy.SizeId, IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0) as DespatchPcs, DespatchDt,(sum(StyleQty) - IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0)) * SaleRate As Amount, IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0) * SaleRate As DespAmount FROM (SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,SizeId FROM (SELECT OrderMas2.Season1 AS SeasonId, OrderStyleDtl.uom, OrderMas2.Gsm, OrderMas.OrdId, OrderMas.Jobno, OrderMas.Finyear,Mas_StyleDesc.StyleDesc,OrderMas.BuyOrdNo, OrderMas.BuyordDt, OrderMas2.DelDt AS DelDt1, OrderMas.OrdDate, OrderMas2.ActDelDt,OrderMas.OrderQty, Mas_Buyer.ShortBuyer, Mas_Buyer.BuyerName, Mas_Merchandiser.MerchName, Mas_Exporter.ShortExp, Mas_Exporter.ExporterName, Mas_Exporter.ExpID,  Mas_Buyer.BuyerID, Mas_Merchandiser.MerchID, SUM(OrderQtyDtl.OrderQty) AS StyleQty, Mas_Fcy.FcyName, OrderQtyDtl.SaleRate, OrderMas.OrderType, OrderMas.grpref, ISNULL(OrderStyleDtl.Fabric1,'''') AS Fabric, Mas_Season.SeasDesc AS SeasonName, OrderQtyDtl.Deldt, CASE WHEN completed = 1 THEN ''C'' WHEN completed = 0 THEN ''R'' WHEN completed <> 2 THEN ''A'' END AS CompFlg, CASE WHEN Ordermas.crate > 0 THEN ExsQty * Crate ELSE ExsQty * Exchangerate END AS OrdValue, OrderQtyDtl.StyleNo, ISNULL(OrderStyleDtl.EntryOption, 1) AS EntryOption,CASE WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 1 THEN ''C'' WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 0 THEN ''R'' WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 3 THEN ''A'' END AS StyleCompFlg,IsNull(OrderMas2.FwdCtRate,0) As ForwardExRate,MasFactory.ExpID as FctryID ,MasFactory.ExporterName  as FctryName,OrderStyleDtl.DelDt as Style_DelDt,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0) StyleWise_Despatch_Completion,OrderQtyDtl.ColID,OrderQtyDtl.SizeId,OrderQtyDtl.lotno ,ISNULL(Mas_Brand.BrandName,''-'') AS  BrandName FROM OrderMas INNER JOIN Mas_Buyer ON OrderMas.BuyerID = Mas_Buyer.BuyerID INNER JOIN Mas_Merchandiser ON OrderMas.MerchID = Mas_Merchandiser.MerchID  INNER JOIN Mas_Exporter ON OrderMas.ExpID = Mas_Exporter.ExpID  INNER JOIN  Vue_Rpt_OrdExcessQtywithSaleRate ON OrderMas.OrdId = Vue_Rpt_OrdExcessQtywithSaleRate.OrdID  INNER JOIN  OrderQtyDtl ON OrderMas.OrdId = OrderQtyDtl.OrdID  INNER JOIN OrderStyleDtl  ON OrderStyleDtl.OrdId=OrderQtyDtl.OrdID and  OrderQtyDtl.StyleNo=OrderStyleDtl.styleNo and OrderQtyDtl.StyleId=OrderStyleDtl.StyleId and OrderStyleDtl.EntryOption=1 inner join Ordermas2 on Ordermas.OrdId=Ordermas2.Ordid  inner join mas_Styledesc on OrderQtyDtl.styleid = mas_Styledesc.styleid  LEFT OUTER JOIN Mas_Exporter as  MasFactory on MasFactory.ExpID = OrderQtyDtl.ProdUnit INNER JOIN Mas_Season ON OrderMas2.Season1 = Mas_Season.SeasID LEFT OUTER JOIN Mas_Fcy ON OrderMas.Fcy = Mas_Fcy.ID LEFT OUTER JOIN Mas_Brand ON Mas_Brand.ID = OrderStyleDtl.BrandID  WHERE Mas_Exporter.Active=''Y'' And RateFor = ''Z'' GROUP BY OrderMas2.Season1, OrderStyleDtl.uom, OrderMas2.Gsm, OrderMas.OrdId, OrderMas.Jobno, OrderMas.Finyear,  OrderMas.BuyOrdNo, OrderMas.BuyordDt,OrderMas2.DelDt, OrderMas.OrderQty, Mas_Buyer.ShortBuyer, Mas_Merchandiser.MerchName, Mas_Exporter.ShortExp, Mas_Exporter.ExpID, Mas_Buyer.BuyerID, Mas_Merchandiser.MerchID, OrderQtyDtl.StyleNo, OrderMas.Completed, OrderMas.Crate, Vue_Rpt_OrdExcessQtywithSaleRate.ExsQty, dbo.Mas_Fcy.ExchangeRate, Mas_Fcy.FcyName, OrderQtyDtl.SaleRate, OrderMas.OrderType, OrderMas.grpref, OrderMas.OrdDate, OrderMas2.ActDelDt, OrderStyleDtl.Fabric1, Mas_Season.SeasDesc, Mas_Exporter.ExporterName, Mas_Buyer.BuyerName, OrderQtyDtl.Deldt, OrderStyleDtl.EntryOption, StyleWise_Completion_OrdHandRpt, mas_Styledesc.StyleDesc, OrderMas2.FwdCtRate, MasFactory.ExpID, MasFactory.ExporterName,OrderStyleDtl.DelDt,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0) ,OrderQtyDtl.ColID,OrderQtyDtl.SizeId,OrderQtyDtl.lotno,Mas_Brand.BrandName   )X  GROUP by SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,SaleRate ,SizeId ) XY  LEFT JOIN  (Select OrdJobNo,StyleNo, DespatchDt, Sizeid, Sum(DespatchPcs) As DespatchPcs  From VueDespatchStock3 Group By OrdJobNo,StyleNo, DespatchDt, Sizeid) VueDespatchStock3 ON XY.OrdId = VueDespatchStock3.Ordjobno and  XY.StyleNo = VueDespatchStock3.StyleNo And XY.SizeId = VueDespatchStock3.SizeId  GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,Xy.SizeId, DespatchDt ) Z GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName, DespatchDt


 UNION
 
 SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,Avg(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName, IsNull(Sum(isnull(DespatchPcs,0)),0) as DespatchPcs, DespatchDt,Sum(Amount) As Amount, Sum(DespAmount) As DespAmount FROM (
 SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,Xy.ColID, IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0) as DespatchPcs, DespatchDt,(sum(StyleQty) - IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0)) * SaleRate As Amount, IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0) * SaleRate As DespAmount FROM (SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,ColID FROM (SELECT OrderMas2.Season1 AS SeasonId, OrderStyleDtl.uom, OrderMas2.Gsm, OrderMas.OrdId, OrderMas.Jobno, OrderMas.Finyear,Mas_StyleDesc.StyleDesc,OrderMas.BuyOrdNo, OrderMas.BuyordDt, OrderMas2.DelDt AS DelDt1, OrderMas.OrdDate, OrderMas2.ActDelDt,OrderMas.OrderQty, Mas_Buyer.ShortBuyer, Mas_Buyer.BuyerName, Mas_Merchandiser.MerchName, Mas_Exporter.ShortExp, Mas_Exporter.ExporterName, Mas_Exporter.ExpID,  Mas_Buyer.BuyerID, Mas_Merchandiser.MerchID, SUM(OrderQtyDtl.OrderQty) AS StyleQty, Mas_Fcy.FcyName, OrderQtyDtl.SaleRate, OrderMas.OrderType, OrderMas.grpref, ISNULL(OrderStyleDtl.Fabric1,'''') AS Fabric, Mas_Season.SeasDesc AS SeasonName, OrderQtyDtl.Deldt, CASE WHEN completed = 1 THEN ''C'' WHEN completed = 0 THEN ''R'' WHEN completed <> 2 THEN ''A'' END AS CompFlg, CASE WHEN Ordermas.crate > 0 THEN ExsQty * Crate ELSE ExsQty * Exchangerate END AS OrdValue, OrderQtyDtl.StyleNo, ISNULL(OrderStyleDtl.EntryOption, 1) AS EntryOption,CASE WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 1 THEN ''C'' WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 0 THEN ''R'' WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 3 THEN ''A'' END AS StyleCompFlg,IsNull(OrderMas2.FwdCtRate,0) As ForwardExRate,MasFactory.ExpID as FctryID ,MasFactory.ExporterName  as FctryName,OrderStyleDtl.DelDt as Style_DelDt,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0) StyleWise_Despatch_Completion,OrderQtyDtl.ColID,OrderQtyDtl.SizeId,OrderQtyDtl.lotno ,ISNULL(Mas_Brand.BrandName,''-'') AS  BrandName FROM OrderMas INNER JOIN Mas_Buyer ON OrderMas.BuyerID = Mas_Buyer.BuyerID INNER JOIN Mas_Merchandiser ON OrderMas.MerchID = Mas_Merchandiser.MerchID  INNER JOIN Mas_Exporter ON OrderMas.ExpID = Mas_Exporter.ExpID  INNER JOIN  Vue_Rpt_OrdExcessQtywithSaleRate ON OrderMas.OrdId = Vue_Rpt_OrdExcessQtywithSaleRate.OrdID  INNER JOIN  OrderQtyDtl ON OrderMas.OrdId = OrderQtyDtl.OrdID  INNER JOIN OrderStyleDtl  ON OrderStyleDtl.OrdId=OrderQtyDtl.OrdID and  OrderQtyDtl.StyleNo=OrderStyleDtl.styleNo and OrderQtyDtl.StyleId=OrderStyleDtl.StyleId and OrderStyleDtl.EntryOption=1 inner join Ordermas2 on Ordermas.OrdId=Ordermas2.Ordid  inner join mas_Styledesc on OrderQtyDtl.styleid = mas_Styledesc.styleid  LEFT OUTER JOIN Mas_Exporter as  MasFactory on MasFactory.ExpID = OrderQtyDtl.ProdUnit INNER JOIN Mas_Season ON OrderMas2.Season1 = Mas_Season.SeasID LEFT OUTER JOIN Mas_Fcy ON OrderMas.Fcy = Mas_Fcy.ID LEFT OUTER JOIN Mas_Brand ON Mas_Brand.ID = OrderStyleDtl.BrandID  WHERE Mas_Exporter.Active=''Y'' And RateFor = ''C'' GROUP BY OrderMas2.Season1, OrderStyleDtl.uom, OrderMas2.Gsm, OrderMas.OrdId, OrderMas.Jobno, OrderMas.Finyear,  OrderMas.BuyOrdNo, OrderMas.BuyordDt,OrderMas2.DelDt, OrderMas.OrderQty, Mas_Buyer.ShortBuyer, Mas_Merchandiser.MerchName, Mas_Exporter.ShortExp, Mas_Exporter.ExpID, Mas_Buyer.BuyerID, Mas_Merchandiser.MerchID, OrderQtyDtl.StyleNo, OrderMas.Completed, OrderMas.Crate, Vue_Rpt_OrdExcessQtywithSaleRate.ExsQty, dbo.Mas_Fcy.ExchangeRate, Mas_Fcy.FcyName, OrderQtyDtl.SaleRate, OrderMas.OrderType, OrderMas.grpref, OrderMas.OrdDate, OrderMas2.ActDelDt, OrderStyleDtl.Fabric1, Mas_Season.SeasDesc, Mas_Exporter.ExporterName, Mas_Buyer.BuyerName, OrderQtyDtl.Deldt, OrderStyleDtl.EntryOption, StyleWise_Completion_OrdHandRpt, mas_Styledesc.StyleDesc, OrderMas2.FwdCtRate, MasFactory.ExpID, MasFactory.ExporterName,OrderStyleDtl.DelDt,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0) ,OrderQtyDtl.ColID,OrderQtyDtl.SizeId,OrderQtyDtl.lotno,Mas_Brand.BrandName   )X  GROUP by SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,SaleRate ,ColID ) XY  LEFT JOIN  (Select OrdJobNo,StyleNo, DespatchDt, ColId, Sum(DespatchPcs) As DespatchPcs  From VueDespatchStock3 Group By OrdJobNo,StyleNo, DespatchDt, ColId) VueDespatchStock3 ON XY.OrdId = VueDespatchStock3.Ordjobno and  XY.StyleNo = VueDespatchStock3.StyleNo And XY.ColId = VueDespatchStock3.ColId  GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,Xy.ColID, DespatchDt ) Z GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName, DespatchDt


 UNION
 
 SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,Avg(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName, IsNull(Sum(isnull(DespatchPcs,0)),0) as DespatchPcs, DespatchDt,Sum(Amount) As Amount, Sum(DespAmount) As DespAmount FROM (
 SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,Xy.SizeId,Xy.ColID, IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0) as DespatchPcs, DespatchDt,(sum(StyleQty) - IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0)) * SaleRate As Amount, IsNull(Sum(isnull(VueDespatchStock3.DespatchPcs,0)),0) * SaleRate As DespAmount FROM (SELECT SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,Sum(OrderQty) as Orderqty,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,sum(StyleQty) as StyleQty,FcyName,(SaleRate) as SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,sum(OrdValue) as OrdValue,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,SizeId, ColID FROM (SELECT OrderMas2.Season1 AS SeasonId, OrderStyleDtl.uom, OrderMas2.Gsm, OrderMas.OrdId, OrderMas.Jobno, OrderMas.Finyear,Mas_StyleDesc.StyleDesc,OrderMas.BuyOrdNo, OrderMas.BuyordDt, OrderMas2.DelDt AS DelDt1, OrderMas.OrdDate, OrderMas2.ActDelDt,OrderMas.OrderQty, Mas_Buyer.ShortBuyer, Mas_Buyer.BuyerName, Mas_Merchandiser.MerchName, Mas_Exporter.ShortExp, Mas_Exporter.ExporterName, Mas_Exporter.ExpID,  Mas_Buyer.BuyerID, Mas_Merchandiser.MerchID, SUM(OrderQtyDtl.OrderQty) AS StyleQty, Mas_Fcy.FcyName, OrderQtyDtl.SaleRate, OrderMas.OrderType, OrderMas.grpref, ISNULL(OrderStyleDtl.Fabric1,'''') AS Fabric, Mas_Season.SeasDesc AS SeasonName, OrderQtyDtl.Deldt, CASE WHEN completed = 1 THEN ''C'' WHEN completed = 0 THEN ''R'' WHEN completed <> 2 THEN ''A'' END AS CompFlg, CASE WHEN Ordermas.crate > 0 THEN ExsQty * Crate ELSE ExsQty * Exchangerate END AS OrdValue, OrderQtyDtl.StyleNo, ISNULL(OrderStyleDtl.EntryOption, 1) AS EntryOption,CASE WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 1 THEN ''C'' WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 0 THEN ''R'' WHEN IsNull(StyleWise_Completion_OrdHandRpt,0) = 3 THEN ''A'' END AS StyleCompFlg,IsNull(OrderMas2.FwdCtRate,0) As ForwardExRate,MasFactory.ExpID as FctryID ,MasFactory.ExporterName  as FctryName,OrderStyleDtl.DelDt as Style_DelDt,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0) StyleWise_Despatch_Completion,OrderQtyDtl.ColID,OrderQtyDtl.SizeId,OrderQtyDtl.lotno ,ISNULL(Mas_Brand.BrandName,''-'') AS  BrandName FROM OrderMas INNER JOIN Mas_Buyer ON OrderMas.BuyerID = Mas_Buyer.BuyerID INNER JOIN Mas_Merchandiser ON OrderMas.MerchID = Mas_Merchandiser.MerchID  INNER JOIN Mas_Exporter ON OrderMas.ExpID = Mas_Exporter.ExpID  INNER JOIN  Vue_Rpt_OrdExcessQtywithSaleRate ON OrderMas.OrdId = Vue_Rpt_OrdExcessQtywithSaleRate.OrdID  INNER JOIN  OrderQtyDtl ON OrderMas.OrdId = OrderQtyDtl.OrdID  INNER JOIN OrderStyleDtl  ON OrderStyleDtl.OrdId=OrderQtyDtl.OrdID and  OrderQtyDtl.StyleNo=OrderStyleDtl.styleNo and OrderQtyDtl.StyleId=OrderStyleDtl.StyleId and OrderStyleDtl.EntryOption=1 inner join Ordermas2 on Ordermas.OrdId=Ordermas2.Ordid  inner join mas_Styledesc on OrderQtyDtl.styleid = mas_Styledesc.styleid  LEFT OUTER JOIN Mas_Exporter as  MasFactory on MasFactory.ExpID = OrderQtyDtl.ProdUnit INNER JOIN Mas_Season ON OrderMas2.Season1 = Mas_Season.SeasID LEFT OUTER JOIN Mas_Fcy ON OrderMas.Fcy = Mas_Fcy.ID LEFT OUTER JOIN Mas_Brand ON Mas_Brand.ID = OrderStyleDtl.BrandID  WHERE Mas_Exporter.Active=''Y'' And RateFor = ''R'' GROUP BY OrderMas2.Season1, OrderStyleDtl.uom, OrderMas2.Gsm, OrderMas.OrdId, OrderMas.Jobno, OrderMas.Finyear,  OrderMas.BuyOrdNo, OrderMas.BuyordDt,OrderMas2.DelDt, OrderMas.OrderQty, Mas_Buyer.ShortBuyer, Mas_Merchandiser.MerchName, Mas_Exporter.ShortExp, Mas_Exporter.ExpID, Mas_Buyer.BuyerID, Mas_Merchandiser.MerchID, OrderQtyDtl.StyleNo, OrderMas.Completed, OrderMas.Crate, Vue_Rpt_OrdExcessQtywithSaleRate.ExsQty, dbo.Mas_Fcy.ExchangeRate, Mas_Fcy.FcyName, OrderQtyDtl.SaleRate, OrderMas.OrderType, OrderMas.grpref, OrderMas.OrdDate, OrderMas2.ActDelDt, OrderStyleDtl.Fabric1, Mas_Season.SeasDesc, Mas_Exporter.ExporterName, Mas_Buyer.BuyerName, OrderQtyDtl.Deldt, OrderStyleDtl.EntryOption, StyleWise_Completion_OrdHandRpt, mas_Styledesc.StyleDesc, OrderMas2.FwdCtRate, MasFactory.ExpID, MasFactory.ExporterName,OrderStyleDtl.DelDt,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0) ,OrderQtyDtl.ColID,OrderQtyDtl.SizeId,OrderQtyDtl.lotno,Mas_Brand.BrandName   )X  GROUP by SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,SaleRate ,SizeId, ColID ) XY  LEFT JOIN  (Select OrdJobNo,StyleNo, DespatchDt, Sizeid,ColID, Sum(DespatchPcs) As DespatchPcs  From VueDespatchStock3 Group By OrdJobNo,StyleNo, DespatchDt, Sizeid, ColId) VueDespatchStock3 ON XY.OrdId = VueDespatchStock3.Ordjobno and  XY.StyleNo = VueDespatchStock3.StyleNo And XY.SizeId = VueDespatchStock3.SizeId And XY.ColID = VueDespatchStock3.ColId  GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName,Xy.SizeId, DespatchDt, Xy.ColID ) Z GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,E