thSaleRate.ExsQty,Mas_Fcy.ExchangeRate, Mas_Fcy.FcyName, OrdQtyClrDtl.SaleRate, OrderMas.OrderType,OrderMas.grpref, OrderMas.OrdDate, OrderMas2.ActDelDt, OrderStyleDtl.Fabric1, Mas_Season.SeasDesc, Mas_Exporter.ExporterName, Mas_Buyer.BuyerName, OrdQtyClrDtl.Deldt, OrderStyleDtl.EntryOption, mas_Styledesc.StyleDesc,OrderMas2.FwdCtRate, MasFactory.ExpID ,MasFactory.ExporterName,OrderStyleDtl.DelDt,OrderStyleDtl.StyleWise_Despatch_Completion ,isnull(OrderStyleDtl.StyleWise_Despatch_Completion,0), OrdQtyClrDtl.CmbClrID,OrdQtyClrDtl.SizeId,OrdQtyClrDtl.lotno,Mas_Brand.BrandName  ) X GROUP by SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,StyleCompFlg,ForwardExRate, Style_DelDt,StyleWise_Despatch_Completion,FctryID,FctryName,BrandName,SaleRate, CmbClrID, SizeID ) XY  LEFT JOIN (Select OrdJobNo,StyleNo, DespatchDt, ColId,SizeId, Sum(DespatchPcs) As DespatchPcs  From VueDespatchStock3 Group By OrdJobNo,StyleNo, DespatchDt, ColId, SizeId)  VueDespatchStock3 ON XY.OrdId = VueDespatchStock3 .Ordjobno and  XY.StyleNo = VueDespatchStock3.StyleNo And XY.CmbClrID = VueDespatchStock3.ColId And XY.SizeId = VueDespatchStock3.SizeId  GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,SaleRate ,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,XY.StyleNo,EntryOption,StyleCompFlg,ForwardExRate, FctryID ,FctryName,Style_DelDt,StyleWise_Despatch_Completion,BrandName, XY.CmbClrID,Xy.SizeId , DespatchDt ) Z GROUP BY SeasonId,uom,Gsm, OrdId,Jobno, Finyear ,StyleDesc ,BuyOrdNo,BuyordDt,DelDt1,OrdDate,ActDelDt,ShortBuyer,BuyerName, MerchName,ShortExp,ExporterName,ExpID,BuyerID, MerchID,FcyName,OrderType,grpref,Fabric,SeasonName,Deldt,CompFlg,StyleNo,EntryOption,St